INSERT INTO skills(id,name_es,name_en,description_es,description_en,area,sort_order) VALUES
(15,'Organización y descripción de colecciones digitales','Digital collection organization and description','Organización de documentos, imágenes y testimonios mediante metadatos y relaciones que facilitan su consulta y su contextualización en la investigación.','Organization of documents, images and testimonies through metadata and relationships supporting consultation and research context.','skill_data',45),
(16,'Arquitectura y publicación de recursos digitales','Digital resource architecture and publication','Diseño de la relación entre datos, aplicaciones y archivos, con procesos de actualización y publicación adaptados al mantenimiento del recurso.','Design of relationships between data, applications and files, with update and publication workflows suited to resource maintenance.','skill_development',65),
(17,'Diseño de flujos de edición y revisión','Editing and review workflow design','Diseño de procesos de preparación, validación, revisión y publicación de contenidos, incluidos paneles editoriales y mecanismos de participación revisada.','Design of content preparation, validation, review and publication workflows, including editorial dashboards and reviewed participation.','skill_text',25),
(18,'Diseño de materiales formativos sobre métodos digitales','Digital methods teaching material design','Elaboración de tutoriales, explicaciones y ejercicios que permiten aprender y reproducir procedimientos de codificación textual y análisis de redes.','Development of tutorials, explanations and exercises for learning and reproducing text encoding and network analysis procedures.','skill_development',105),
(19,'Análisis de datos humanísticos','Humanities data analysis','Preparación y análisis de datos de investigación para explorar relaciones, distribuciones y patrones en corpus textuales y bibliográficos.','Preparation and analysis of research data to explore relationships, distributions and patterns in textual and bibliographic corpora.','skill_analysis',108);
